// From Algolia example
// https://github.com/algolia/react-instantsearch
const ALGOLIA_APP_ID = 'latency'
const ALGOLIA_SEARCH_API_KEY = '6be0576ff61c053d5f9a3225e2a90f76'

type SearchOptions = {
  indexName: string
  query: string
  pageParam: number
  hitsPerPage: number
}

export async function search<TData>({
  indexName,
  query,
  pageParam,
  hitsPerPage = 10,
}: SearchOptions): Promise<{
  hits: Array<Hit<TData>>
  nextPage: number | undefined
}> {
  const client = searchClient(ALGOLIA_APP_ID, ALGOLIA_SEARCH_API_KEY)

  console.log('algolia:search', { indexName, query, pageParam, hitsPerPage })

  const { hits, page, nbPages } = await client.searchSingleIndex<TData>({
    indexName,
    searchParams: { query, page: pageParam, hitsPerPage },
  })

  const nextPage = page + 1 < nbPages ? page + 1 : undefined

  return { hits, nextPage }
}

import { skipToken, useInfiniteQuery } from '@tanstack/react-query'
import { search } from './algolia'

export type UseAlgoliaOptions = {
  indexName: string
  query: string
  hitsPerPage?: number
  staleTime?: number
  gcTime?: number
}

export default function useAlgolia<TData>({
  indexName,
  query,
  hitsPerPage = 10,
  staleTime,
  gcTime,
}: UseAlgoliaOptions) {
  const queryInfo = useInfiniteQuery({
    queryKey: ['algolia', indexName, query, hitsPerPage],
    queryFn: query
      ? ({ pageParam }) =>
          search<TData>({ indexName, query, pageParam, hitsPerPage })
      : skipToken,
    initialPageParam: 0,
    getNextPageParam: (lastPage) => lastPage.nextPage,
    staleTime,
    gcTime,
  })

  const hits = queryInfo.data?.pages.map((page) => page.hits).flat()

  return { ...queryInfo, hits }
}

